// Package countries is a short, offline fact sheet for every country:
// capital, population, languages, currency, calling code, driving side, time
// zones and neighbours. countries.json is generated by tools/countries/build.py
// from world-countries (ODbL), the World Bank (CC BY 4.0), Wikidata (CC0) and
// the IANA tz database.
package countries

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strings"
	"sync"
)

//go:embed countries.json
var raw []byte

// Currency is one legal tender of a country.
type Currency struct {
	Code   string `json:"code"`
	Name   string `json:"name"`
	Symbol string `json:"symbol"`
}

// Country is the fact sheet.
type Country struct {
	Code           string     `json:"code"`
	Name           string     `json:"name"`
	Official       string     `json:"official"`
	Capital        []string   `json:"capital"`
	Region         string     `json:"region"`
	Subregion      string     `json:"subregion"`
	Population     int64      `json:"population"`
	PopulationYear int        `json:"population_year"`
	AreaKm2        float64    `json:"area_km2"`
	Languages      []string   `json:"languages"`
	Currencies     []Currency `json:"currencies"`
	CallingCode    string     `json:"calling_code"`
	TLD            string     `json:"tld"`
	Drives         string     `json:"drives"` // left | right | ""
	Timezones      []string   `json:"timezones"`
	Borders        []string   `json:"borders"`
	Landlocked     bool       `json:"landlocked"`
	LatLng         []float64  `json:"latlng"`
	Demonym        string     `json:"demonym"`
	Independent    bool       `json:"independent"`
}

var (
	once   sync.Once
	all    []Country
	byCode map[string]*Country
	// Sources names the data sets, for the credits.
	Sources string
)

func load() {
	once.Do(func() {
		var f struct {
			Sources   string    `json:"sources"`
			Countries []Country `json:"countries"`
		}
		if err := json.Unmarshal(raw, &f); err != nil {
			panic("countries.json: " + err.Error())
		}
		all, Sources = f.Countries, f.Sources
		sort.Slice(all, func(i, j int) bool { return all[i].Name < all[j].Name })
		byCode = make(map[string]*Country, len(all))
		for i := range all {
			byCode[all[i].Code] = &all[i]
		}
	})
}

// All returns every country, by name.
func All() []Country { load(); return all }

// Get returns the country with an ISO 3166-1 alpha-2 code, or nil.
func Get(code string) *Country {
	load()
	return byCode[strings.ToUpper(strings.TrimSpace(code))]
}
